#define MAXN 100
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

Point poly[MAXN];
int n;

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double dist(Point a, Point b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

double pointToLineDist(Point p, Point a, Point b) {
    return fabs(cross(a, b, p)) / dist(a, b);
}

// Check if a circle of radius r can be placed inside the polygon
int canFit(double r) {
    // We try to find a point inside polygon with distance >= r to all edges
    // Using linear programming: distance to each edge >= r
    // For convex polygon, we shift each edge inward by r and check intersection
    double left = -1e9, right = 1e9, bottom = -1e9, top = 1e9;
    for (int i = 0; i < n; i++) {
        Point a = poly[i];
        Point b = poly[(i + 1) % n];
        double dx = b.x - a.x;
        double dy = b.y - a.y;
        double len = sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        // outward normal (assuming CCW)
        double nx = -dy;
        double ny = dx;
        double d = nx * a.x + ny * a.y;
        // inward half-plane: nx*x + ny*y <= d - r
        if (fabs(nx) > fabs(ny)) {
            double xlim = (d - r - ny * 0) / nx;
            if (nx > 0) right = fmin(right, xlim);
            else left = fmax(left, xlim);
        } else {
            double ylim = (d - r - nx * 0) / ny;
            if (ny > 0) top = fmin(top, ylim);
            else bottom = fmax(bottom, ylim);
        }
    }
    return left <= right + EPS && bottom <= top + EPS;
}

