// Distance from point p to segment (a,b) line
double distToEdge(P p, P a, P b) {
    double dx = b.x-a.x, dy = b.y-a.y;
    double len = sqrt(dx*dx+dy*dy);
    return ((dx)*(p.y-a.y) - (dy)*(p.x-a.x)) / len;
}

// Check if point p is inside or on the polygon (CCW)
int inside(P p) {
    for(int i=0;i<n;i++){
        int j=(i+1)%n;
        if(cross(poly[i],poly[j],p) < -EPS) return 0;
    }
    return 1;
}

// Ternary search: maximize f(x,y) = min distance to all edges
// f is concave on the convex polygon

double minDist(P p) {
    double res = 1e18;
    for(int i=0;i<n;i++){
        int j=(i+1)%n;
        double d = distToEdge(p, poly[i], poly[j]);
        if(d < res) res = d;
    }
    return res;
}

