typedef struct {
    double x, y;
} Point;

static double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static double dist_to_line(Point a, Point b, Point p) {
    double A = b.y - a.y;
    double B = a.x - b.x;
    double C = -(A * a.x + B * a.y);
    return fabs(A * p.x + B * p.y + C) / sqrt(A * A + B * B);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point poly[1005];
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &poly[i].x, &poly[i].y);
    }

    /* Ensure counterclockwise orientation */
    double area2 = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        area2 += poly[i].x * poly[j].y - poly[j].x * poly[i].y;
    }
    if (area2 < 0) {
        for (int i = 0; i < n / 2; i++) {
            Point tmp = poly[i];
            poly[i] = poly[n - 1 - i];
            poly[n - 1 - i] = tmp;
        }
    }

    /* Half-planes: for each edge, inside means cross(edge_start, edge_end, p) >= 0 */

    /* Start from centroid as an interior point */
    Point cur = {0.0, 0.0};
    for (int i = 0; i < n; i++) {
        cur.x += poly[i].x;
        cur.y += poly[i].y;
    }
    cur.x /= n;
    cur.y /= n;

    /* Hill-climbing / shrinking-step search over convex function max distance-to-edges */
    double minx = poly[0].x, maxx = poly[0].x, miny = poly[0].y, maxy = poly[0].y;
    for (int i = 1; i < n; i++) {
        if (poly[i].x < minx) minx = poly[i].x;
        if (poly[i].x > maxx) maxx = poly[i].x;
        if (poly[i].y < miny) miny = poly[i].y;
        if (poly[i].y > maxy) maxy = poly[i].y;
    }
    double step = fmax(maxx - minx, maxy - miny);

    for (int iter = 0; iter < 200; iter++) {
        Point best = cur;
        double bestVal = 1e100;

        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                Point np = {cur.x + dx * step, cur.y + dy * step};

                int inside = 1;
                double val = 1e100;
                for (int i = 0; i < n; i++) {
                    int j = (i + 1) % n;
                    double cr = cross(poly[i], poly[j], np);
                    if (cr < -1e-12) {
                        inside = 0;
                        break;
                    }
                    double d = dist_to_line(poly[i], poly[j], np);
                    if (d < val) val = d;
                }

                if (inside && val < bestVal) {
                    /* We minimize negative? No, want maximize minimum distance.
                       So compare appropriately below. */
                }
            }
        }

        double curBest = -1.0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                Point np = {cur.x + dx * step, cur.y + dy * step};

                int inside = 1;
                double val = 1e100;
                for (int i = 0; i < n; i++) {
                    int j = (i + 1) % n;
                    double cr = cross(poly[i], poly[j], np);
                    if (cr < -1e-12) {
                        inside = 0;
                        break;
                    }
                    double d = dist_to_line(poly[i], poly[j], np);
                    if (d < val) val = d;
                }

                if (inside && val > curBest) {
                    curBest = val;
                    best = np;
                }
            }
        }

        cur = best;
        step *= 0.5;
    }

    double ans = 1e100;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        double d = dist_to_line(poly[i], poly[j], cur);
        if (d < ans) ans = d;
    }

    printf("%.5f\n", ans);
    return 0;
}

