using ld = long double;
const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x, ld y) : x(x), y(y) {}
    Point operator-(const Point &p) const { return Point(x - p.x, y - p.y); }
    Point operator+(const Point &p) const { return Point(x + p.x, y + p.y); }
    Point operator*(ld s) const { return Point(x * s, y * s); }
    ld cross(const Point &p) const { return x * p.y - y * p.x; }
    ld dot(const Point &p) const { return x * p.x + y * p.y; }
    ld length() const { return sqrtl(x * x + y * y); }
    Point normalized() const {
        ld len = length();
        return Point(x / len, y / len);
    }
};

// Line intersection of lines a->b and c->d
Point intersect(Point a, Point b, Point c, Point d) {
    ld a1 = b.y - a.y, b1 = a.x - b.x, c1 = a1 * a.x + b1 * a.y;
    ld a2 = d.y - c.y, b2 = c.x - d.x, c2 = a2 * c.x + b2 * c.y;
    ld det = a1 * b2 - a2 * b1;
    return Point((b2 * c1 - b1 * c2) / det, (a1 * c2 - a2 * c1) / det);
}

// Offset polygon edges inward by d
vector<Point> offsetPolygon(const vector<Point> &poly, ld d) {
    int n = poly.size();
    vector<Point> result;
    for (int i = 0; i < n; i++) {
        Point a = poly[i];
        Point b = poly[(i + 1) % n];
        Point dir = (b - a).normalized();
        Point normal(-dir.y, dir.x);
        Point a2 = a + normal * d;
        Point b2 = b + normal * d;

        Point prev_dir = (a - poly[(i - 1 + n) % n]).normalized();
        Point prev_normal(-prev_dir.y, prev_dir.x);
        Point prev_a = poly[(i - 1 + n) % n] + prev_normal * d;
        Point prev_b = a + prev_normal * d;

        result.push_back(intersect(prev_a, prev_b, a2, b2));
    }
    return result;
}

// Check if offset polygon has positive area
bool isValid(const vector<Point> &poly) {
    ld area = 0;
    int n = poly.size();
    for (int i = 0; i < n; i++)
        area += poly[i].cross(poly[(i + 1) % n]);
    return fabs(area) > EPS;
}

