#include <bits/stdc++.h>
using namespace std;

typedef double ld;
const ld EPS = 1e-9;

struct P {
    ld x, y;
    P(ld x=0, ld y=0): x(x), y(y){}
    P operator-(P o){ return {x-o.x, y-o.y}; }
    P operator+(P o){ return {x+o.x, y+o.y}; }
    P operator*(ld t){ return {x*t, y*t}; }
    ld dot(P o){ return x*o.x + y*o.y; }
    ld cross(P o){ return x*o.y - y*o.x; }
    ld norm(){ return sqrt(x*x+y*y); }
};

// Half plane: ax + by <= c  (points satisfying this are "inside")
// Represented as: left side of directed line from p to p+d
struct HP {
    P p, d; // point on line, direction
    ld angle;
    HP(){}
    HP(P p, P d): p(p), d(d), angle(atan2(d.y, d.x)){}
};

bool onLeft(HP h, P p){
    return h.d.cross(p - h.p) > EPS;
}

P lineIntersect(HP h1, HP h2){
    P u = h2.p - h1.p;
    ld t = h2.d.cross(u) / h1.d.cross(h2.d);
    return h1.p + h1.d * t;
}

bool hpIntersect(vector<HP> hs, vector<P>& poly){
    int n = hs.size();
    sort(hs.begin(), hs.end(), [](HP a, HP b){
        if(fabs(a.angle - b.angle) > EPS) return a.angle < b.angle;
        return b.d.cross(a.p - b.p) > 0;
    });
    // remove duplicates
    vector<HP> h;
    for(int i=0;i<n;i++){
        if(i==0 || fabs(hs[i].angle-hs[i-1].angle)>EPS)
            h.push_back(hs[i]);
    }
    n = h.size();
    if(n < 3) return false;
    deque<HP> dh;
    deque<P> dp;
    dh.push_back(h[0]); dh.push_back(h[1]);
    dp.push_back(lineIntersect(h[0],h[1]));
    for(int i=2;i<n;i++){
        while(dp.size() && !onLeft(h[i], dp.back())){
            dp.pop_back(); dh.pop_back();
        }
        while(dp.size() && !onLeft(h[i], dp.front())){
            dp.pop_front(); dh.pop_front();
        }
        dh.push_back(h[i]);
        dp.push_back(lineIntersect(dh[dh.size()-2], dh.back()));
    }
    while(dp.size() && !onLeft(dh.front(), dp.back())){
        dp.pop_back(); dh.pop_back();
    }
    if(dh.size()<3) return false;
    poly.clear();
    for(auto p: dp) poly.push_back(p);
    return true;
}

