#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
};

static const double EPS = 1e-12;

double cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double distPointLine(const Point& p, const Point& a, const Point& b) {
    // Distance from point p to the infinite line through a,b
    double A = b.y - a.y;
    double B = a.x - b.x;
    double C = -(A * a.x + B * a.y);
    return fabs(A * p.x + B * p.y + C) / sqrt(A * A + B * B);
}

bool insideConvex(const vector<Point>& poly, const Point& p) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        if (cross(poly[i], poly[j], p) < -EPS) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Point> poly(n);
    for (int i = 0; i < n; ++i) {
        cin >> poly[i].x >> poly[i].y;
    }

    // Ensure counterclockwise orientation
    double area2 = 0.0;
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        area2 += poly[i].x * poly[j].y - poly[j].x * poly[i].y;
    }
    if (area2 < 0) reverse(poly.begin(), poly.end());

    // The answer is the radius of the largest inscribed circle.
    // For a convex polygon, feasibility of radius r means there exists a point
    // inside all half-planes shifted inward by distance r.
    // We test feasibility by checking whether some point remains after clipping.
    auto feasible = [&](double r) -> bool {
        vector<Point> candidate = poly;

        // Since polygon is convex and not huge in typical tasks, we can instead
        // search for a point maximizing minimum distance using nested ternary search.
        // But for robustness, here we test via half-plane constraints using
        // intersection of all shifted half-planes sampled by polygon clipping.

        // Clip current polygon by each inward-shifted edge half-plane.
        auto clipWithEdge = [&](const vector<Point>& subject, const Point& a, const Point& b) {
            vector<Point> out;
            if (subject.empty()) return out;

            double dx = b.x - a.x, dy = b.y - a.y;
            double len = sqrt(dx * dx + dy * dy);
            // For CCW polygon, inward normal is (-dy, dx) / len
            double nx = -dy / len, ny = dx / len;

            // Shift line inward by distance r: points p satisfy
            // cross(a,b,p) >= r * |b-a|
            auto val = [&](const Point& p) {
                return cross(a, b, p) - r * len;
            };

            int m = (int)subject.size();
            for (int i = 0; i < m; ++i) {
                Point P = subject[i];
                Point Q = subject[(i + 1) % m];
                double vP = val(P), vQ = val(Q);
                bool inP = vP >= -EPS;
                bool inQ = vQ >= -EPS;

                if (inP && inQ) {
                    out.push_back(Q);
                } else if (inP && !inQ) {
                    // leaving
                    double t = vP / (vP - vQ);
                    Point I{P.x + (Q.x - P.x) * t, P.y + (Q.y - P.y) * t};
                    out.push_back(I);
                } else if (!inP && inQ) {
                    // entering
                    double t = vP / (vP - vQ);
                    Point I{P.x + (Q.x - P.x) * t, P.y + (Q.y - P.y) * t};
                    out.push_back(I);
                    out.push_back(Q);
                }
            }
            return out;
        };

        for (int i = 0; i < n; ++i) {
            int j = (i + 1) % n;
            candidate = clipWithEdge(candidate, poly[i], poly[j]);
            if (candidate.empty()) return false;
        }
        return !candidate.empty();
    };

    double lo = 0.0, hi = 0.0;

    // Upper bound: diameter-ish safe bound from bounding box
    double minx = poly[0].x, maxx = poly[0].x, miny = poly[0].y, maxy = poly[0].y;
    for (auto &p : poly) {
        minx = min(minx, p.x);
        maxx = max(maxx, p.x);
        miny = min(miny, p.y);
        maxy = max(maxy, p.y);
    }
    hi = hypot(maxx - minx, maxy - miny);

    for (int it = 0; it < 80; ++it) {
        double mid = (lo + hi) * 0.5;
        if (feasible(mid)) lo = mid;
        else hi = mid;
    }

    cout << fixed << setprecision(10) << lo << "\n";
    return 0;
}

import sys
import math


# ------------------------------------------------------------
# Geometry helpers
# ------------------------------------------------------------

def dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def point_segment_distance(p, a, b):
    ax, ay = a
    bx, by = b
    px, py = p

    vx, vy = bx - ax, by - ay
    wx, wy = px - ax, py - ay

    vv = vx * vx + vy * vy
    if vv == 0:
        return math.hypot(px - ax, py - ay)

    t = (wx * vx + wy * vy) / vv
    if t < 0:
        return math.hypot(px - ax, py - ay)
    if t > 1:
        return math.hypot(px - bx, py - by)

    projx = ax + t * vx
    projy = ay + t * vy
    return math.hypot(px - projx, py - projy)


def area2(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def line_intersection(a1, a2, b1, b2):
    x1, y1 = a1
    x2, y2 = a2
    x3, y3 = b1
    x4, y4 = b2

    den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if abs(den) < 1e-15:
        return None

    px = ((x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4)) / den
    py = ((x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4)) / den
    return (px, py)


