# Half-plane clipping by offset lines
# For each polygon edge (vi -> vj), inside is the left side.
# To test if inradius >= r, clip the polygon by all inward-shifted
# supporting lines at distance r. If non-empty => feasible.
# ------------------------------------------------------------

def ensure_ccw(poly):
    s = 0.0
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    if s < 0:
        poly.reverse()
    return poly


def clip_with_offset_halfplane(poly, a, b, r):
    # Original line through a->b, inward is left side.
    # Shift line inward by distance r along left normal.
    dx = b[0] - a[0]
    dy = b[1] - a[1]
    L = math.hypot(dx, dy)
    nx = -dy / L
    ny = dx / L

    # Shifted line points
    sa = (a[0] + nx * r, a[1] + ny * r)
    sb = (b[0] + nx * r, b[1] + ny * r)

    def inside(p):
        return area2(sa, sb, p) >= -1e-12

    res = []
    m = len(poly)
    if m == 0:
        return res

    for i in range(m):
        cur = poly[i]
        nxt = poly[(i + 1) % m]
        ic = inside(cur)
        inx = inside(nxt)

        if ic and inx:
            res.append(nxt)
        elif ic and not inx:
            inter = line_intersection(cur, nxt, sa, sb)
            if inter is not None:
                res.append(inter)
        elif not ic and inx:
            inter = line_intersection(cur, nxt, sa, sb)
            if inter is not None:
                res.append(inter)
            res.append(nxt)

    return res


def feasible(original_poly, r):
    poly = original_poly[:]
    n = len(original_poly)
    for i in range(n):
        a = original_poly[i]
        b = original_poly[(i + 1) % n]
        poly = clip_with_offset_halfplane(poly, a, b, r)
        if not poly:
            return False
    return True


