    // Check if there is a point inside polygon at least 'd' away from all edges
    static boolean canPlace(Point[] poly, double d) {
        int n = poly.length;
        // Move each edge inward by distance d
        // Represent constraints as half-planes: ax + by <= c
        double[] a = new double[n];
        double[] b = new double[n];
        double[] c = new double[n];
        for (int i = 0; i < n; i++) {
            Point p1 = poly[i];
            Point p2 = poly[(i + 1) % n];
            double dx = p2.x - p1.x;
            double dy = p2.y - p1.y;
            double len = Math.hypot(dx, dy);
            // outward normal (to the right of edge direction)
            double nx = -dy / len;
            double ny = dx / len;
            // For a convex polygon (counterclockwise), the interior is to the left.
            // We want the line shifted inward: nx*x + ny*y <= -d? Check orientation.
            // For CCW polygon: interior is left of edge direction => outward normal is (dy, -dx)/len or (-dy, dx)/len?
            // Let's check: edge from p1 to p2, interior is left: cross(p2-p1, interior-p1) > 0.
            // The outward normal pointing right of edge is (dy, -dx)/len.
            // Inward normal pointing left is (-dy, dx)/len.
            // For point p inside: dot(inwardNormal, p - p1) >= 0.
            // Condition: inwardNormal.x * x + inwardNormal.y * y >= inwardNormal.x * p1.x + inwardNormal.y * p1.y
            // To shift inward by d: inwardNormal.x * x + inwardNormal.y * y >= inwardNormal.x * p1.x + inwardNormal.y * p1.y + d
            double inx = -dy / len;
            double iny = dx / len;
            a[i] = inx;
            b[i] = iny;
            c[i] = inx * p1.x + iny * p1.y + d;
        }

        // Use linear programming: find if intersection of half-planes ax+by <= c is non-empty
        // We'll use a simple 2D half-plane intersection by bounding box search.
        // Since polygon is convex and small, we can just sample inside.
        // More robust: binary search on x, then y.
        double loX = -1e9, hiX = 1e9, loY = -1e9, hiY = 1e9;
