            loY = Math.max(loY, p.y - 1000);
            hiY = Math.min(hiY, p.y + 1000);
        }

        // Check a grid of points (or use simplex-like check); we'll binary search
        for (int iter = 0; iter < 200; iter++) {
            double midX = (loX + hiX) / 2;
            double midY = (loY + hiY) / 2;
            boolean feasible = true;
            for (int i = 0; i < n; i++) {
                if (a[i] * midX + b[i] * midY > c[i] + EPS) {
                    feasible = false;
                    break;
                }
            }
            // We need to search properly. Use a simple approach: check many random points
        }

        // Better approach: use half-plane intersection algorithm
        // For simplicity, let's just check many candidate points from polygon interior
        // Actually, we can use binary search on radius with 'point-in-polygon with offset edges' check by solving linear constraints.
        // I'll use a direct half-plane intersection with bounding box.

        double xmin = Double.MAX_VALUE, xmax = -Double.MAX_VALUE;
        double ymin = Double.MAX_VALUE, ymax = -Double.MAX_VALUE;
        for (Point p : poly) {
            xmin = Math.min(xmin, p.x);
            xmax = Math.max(xmax, p.x);
            ymin = Math.min(ymin, p.y);
            ymax = Math.max(ymax, p.y);
        }

        // Check many points in bounding box
        for (double x = xmin; x <= xmax; x += (xmax - xmin) / 200) {
            for (double y = ymin; y <= ymax; y += (ymax - ymin) / 200) {
                boolean ok = true;
                for (int i = 0; i < n; i++) {
                    if (a[i] * x + b[i] * y > c[i] + EPS) {
                        ok = false;
                        break;
                    }
                }
                if (ok) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
