public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static int n;
    static Point[] p;

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static double distToLine(Point a, Point b, double x, double y) {
        double A = b.y - a.y;
        double B = a.x - b.x;
        double C = -(A * a.x + B * a.y);
        return Math.abs(A * x + B * y + C) / Math.hypot(A, B);
    }

    // For a point inside a convex polygon, distance to sea = minimum distance to all edges
    static double f(double x, double y) {
        double res = Double.POSITIVE_INFINITY;
        for (int i = 0; i < n; i++) {
            Point a = p[i];
            Point b = p[(i + 1) % n];
            res = Math.min(res, distToLine(a, b, x, y));
        }
        return res;
    }

    // Since the function is concave over a convex polygon, nested ternary search works.
    static double searchY(double x) {
        double low = p[0].y, high = p[0].y;
        for (int i = 1; i < n; i++) {
            low = Math.min(low, p[i].y);
            high = Math.max(high, p[i].y);
        }

        // Restrict to vertical slice inside polygon
        double ymin = Double.POSITIVE_INFINITY;
        double ymax = Double.NEGATIVE_INFINITY;

        for (int i = 0; i < n; i++) {
            Point a = p[i], b = p[(i + 1) % n];
            if (Math.abs(a.x - b.x) < 1e-12) {
                if (Math.abs(x - a.x) < 1e-12) {
                    ymin = Math.min(ymin, Math.min(a.y, b.y));
                    ymax = Math.max(ymax, Math.max(a.y, b.y));
                }
            } else {
                double minx = Math.min(a.x, b.x), maxx = Math.max(a.x, b.x);
                if (x >= minx - 1e-12 && x <= maxx + 1e-12) {
                    double y = a.y + (b.y - a.y) * (x - a.x) / (b.x - a.x);
                    ymin = Math.min(ymin, y);
                    ymax = Math.max(ymax, y);
                }
            }
        }

        low = ymin;
        high = ymax;

        for (int it = 0; it < 100; it++) {
            double m1 = (2 * low + high) / 3.0;
            double m2 = (low + 2 * high) / 3.0;
            if (f(x, m1) < f(x, m2)) low = m1;
            else high = m2;
        }
        return f(x, (low + high) / 2.0);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        p = new Point[n];

        double minX = Double.POSITIVE_INFINITY;
        double maxX = Double.NEGATIVE_INFINITY;

        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            p[i] = new Point(x, y);
            minX = Math.min(minX, x);
            maxX = Math.max(maxX, x);
        }

        // Outer ternary search on x
        double low = minX, high = maxX;
        for (int it = 0; it < 100; it++) {
            double m1 = (2 * low + high) / 3.0;
            double m2 = (low + 2 * high) / 3.0;
            if (searchY(m1) < searchY(m2)) low = m1;
            else high = m2;
        }

        double ans = searchY((low + high) / 2.0);
        System.out.printf(Locale.US, "%.10f%n", ans);
    }
